import base64import requestsOLLAMA_URL = "http://localhost:11434/api/chat"MODEL = "qwen3-vl:4b-instruct"def generate_copy(image_path, prompt):    with open(image_path, "rb") as image_file:        image_base64 = base64.b64encode(            image_file.read()        ).decode("utf-8")    payload = {        "model": MODEL,        "messages": [            {                "role": "user",                "content": prompt,                "images": [image_base64]            }        ],        "stream": False,        "think": False,        "options": {            "num_ctx": 8192,            "num_predict": 150        }    }    try:        response = requests.post(            OLLAMA_URL,            json=payload,            timeout=120        )        response.raise_for_status()    except requests.exceptions.ConnectionError:        raise RuntimeError(            "No se pudo conectar con Ollama. "            "Asegúrate de que Ollama esté ejecutándose."        )    except requests.exceptions.Timeout:        raise RuntimeError(            "Ollama tardó demasiado en responder."        )    except requests.exceptions.HTTPError:        raise RuntimeError(            f"Ollama devolvió un error: {response.text}"        )    result = response.json()    return result["message"]["content"]